// Hand-written stub for a package that publishes a registry of applications.
//
// It stands for the collection nothing in a repository can enumerate: the
// members are contributed by whoever installed the package, in code that is not
// here at all, so a mount over this list installs an unknown number of routers.
// The reader's answer to that is one row naming the collection and the mount,
// which is a missing address rather than a wrong one.

import type { Router } from '@koa/router';

export interface HostHook {
  type: string;
  value: Router;
}

export declare function hostHooks(type: string): HostHook[];
